CREATE TABLE IF NOT EXISTS admin_role(role_code VARCHAR(64) PRIMARY KEY,display_name VARCHAR(128) NOT NULL,enabled TINYINT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS admin_role_permission(role_code VARCHAR(64) NOT NULL,permission_code VARCHAR(96) NOT NULL,granted_at DATETIME(3) NOT NULL,PRIMARY KEY(role_code,permission_code),CONSTRAINT fk_admin_role_permission_role FOREIGN KEY(role_code) REFERENCES admin_role(role_code));
CREATE TABLE IF NOT EXISTS admin_operator_role(operator_id BIGINT UNSIGNED NOT NULL,role_code VARCHAR(64) NOT NULL,enabled TINYINT NOT NULL DEFAULT 1,granted_by BIGINT UNSIGNED NOT NULL,granted_at DATETIME(3) NOT NULL,PRIMARY KEY(operator_id,role_code),KEY idx_admin_operator_role(role_code,enabled),CONSTRAINT fk_admin_operator_role_role FOREIGN KEY(role_code) REFERENCES admin_role(role_code));
CREATE TABLE IF NOT EXISTS admin_authorization_audit(audit_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,request_id VARCHAR(128) NOT NULL,operator_id BIGINT UNSIGNED NOT NULL,permission_code VARCHAR(96) NOT NULL,http_method VARCHAR(8) NOT NULL,request_path VARCHAR(256) NOT NULL,decision VARCHAR(16) NOT NULL,occurred_at DATETIME(3) NOT NULL,KEY idx_admin_auth_operator(operator_id,occurred_at),KEY idx_admin_auth_denial(decision,occurred_at));
